require dirname(__DIR__).'/includes/bootstrap.php';require_permission('campaigns.manage');verify_csrf();$name=trim((string)($_POST['name']??''));$start=(string)($_POST['start_date']??'');$deadline=(string)($_POST['deadline']??'');$target=(int)($_POST['target_count']??0);if($name===''||!strtotime($start)||!strtotime($deadline)||$target<1||strtotime($deadline)<strtotime($start)){flash('error','Enter a valid campaign name, dates, and target.');redirect('campaigns.php');}$pdo=db();$manager=(int)($_POST['manager_employee_id']??0)?:null;$status=in_array($_POST['status']??'',['draft','active'],true)?$_POST['status']:'active';$pdo->prepare('INSERT INTO campaigns(name,start_date,deadline,target_count,count_statuses_json,timezone,daily_distribution,manager_employee_id,status,notes,created_by,updated_by) VALUES(?,?,?,?,JSON_ARRAY("verified"),?,"even",?,?,?,?,?)')->execute([$name,$start,$deadline,$target,config('app.timezone'),$manager,$status,trim((string)($_POST['notes']??''))?:null,current_user_id(),current_user_id()]);$id=(int)$pdo->lastInsertId();audit('campaign.created','campaign',$id,['target'=>$target]);flash('success','Campaign created.');redirect('campaigns.php');
